{
  "summary": "Construct a portable calibration instrument from the reference points, but retain the ordinary shared route when its outputs tie and complete modeled costs are lower.",
  "opportunities": [
    {
      "id": "portable-reference-passport",
      "title": "Portable reference passport with independently replayable arithmetic",
      "hypothesis": "An inspectable conversion and source record could make shared reference access usable across laboratories without requiring each to own an instrument. Actual measurement quality and participant willingness remain untested.",
      "requiredCapabilities": [
        "replayable-comparable-readings"
      ],
      "evidenceIds": [
        "synthetic-calibration-points-v1"
      ],
      "assumptions": [
        "All sensor values, costs, benefits and outside options are synthetic teaching inputs.",
        "The raw/reference relationship is assumed affine on [100,500]; two endpoints do not establish physical linearity, stability or uncertainty.",
        "No actual customer, supplier quote, willingness to pay, funding receipt, contract or physical measurement is represented.",
        "The proposal was authored by an included assistant from this objective during product development; it is not autonomous discovery by the application or evidence of scientific novelty."
      ],
      "experiment": {
        "procedure": "Construct (reading - 100) × 25, retain a calibrated-range flag, compare frozen numerical cases against direct algebra, reject an omitted offset, and recompute every participant payoff.",
        "acceptance": "Exact agreement on declared numerical cases; protected independently prepared cases are evaluated separately. No participant falls below its declared outside option.",
        "failure": "Incorrect conversion, unrecognized range violation, unfavorable participant payoff or conventional complete route advantage prevents an invention-superiority claim."
      },
      "alternatives": [
        "Ordinary shared reference plus direct algebra",
        "Separate external verification",
        "Non-entry"
      ]
    }
  ],
  "capabilities": [
    {
      "id": "ordinary-shared-route",
      "requires": [
        "synthetic-calibration-evidence",
        "voluntary-laboratories"
      ],
      "provides": [
        "replayable-comparable-readings"
      ],
      "costMinor": 30000
    },
    {
      "id": "portable-harness-construction",
      "requires": [
        "synthetic-calibration-evidence",
        "voluntary-laboratories"
      ],
      "provides": [
        "replayable-comparable-readings"
      ],
      "costMinor": 33000
    }
  ],
  "uncertainties": [
    "Real sensor behavior, uncertainty, source authenticity, access rights, prices, participant preferences, funding timing and actual resource bills are unknown.",
    "No actual multi-model comparison or measured AI-versus-human productivity result is supplied."
  ]
}
